import { Fragment, useEffect, useMemo, useState, type CSSProperties, type FormEvent, type ReactNode } from 'react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { ErrorBoundary } from '@/components/error-boundary';
import { Toaster } from '@/components/ui/toaster';
import { TooltipProvider } from '@/components/ui/tooltip';
import { Link, Route, Router as WouterRouter, Switch, useLocation } from 'wouter';
import {
  AlarmClock, ArrowRight, ArrowUpRight, BookOpen, CalendarDays, CalendarPlus,
  ChartNoAxesCombined, Check, CheckCircle2, ChevronLeft, ChevronRight, Circle,
  CircleCheck, Clock3, Columns3, Coffee, Filter, Home, Lightbulb, List,
  MoreHorizontal, Pause, Play, Plus, Search, Send, Settings,
  SlidersHorizontal, SquareCheckBig, Target, Timer, TrendingUp,
  WandSparkles, X,
  Sparkles,
} from 'lucide-react';
import { seedState, today, type AcademicItem, type AssistantMessage, type Course, type ScheduleEvent, type StudyPlan, type TimoraState } from '@/lib/timora-data';

const queryClient = new QueryClient();
const links = [
  { section: 'OVERVIEW', items: [{ href: '/', label: 'Dashboard', Icon: Home }] },
  { section: 'ACADEMIC', items: [{ href: '/courses', label: 'My courses', Icon: BookOpen }, { href: '/assignments', label: 'Assignments & exams', Icon: SquareCheckBig }] },
  { section: 'PRODUCTIVITY', items: [{ href: '/calendar', label: 'Calendar', Icon: CalendarDays }, { href: '/planner', label: 'Study planner', Icon: WandSparkles }, { href: '/focus', label: 'Focus sessions', Icon: Timer }] },
  { section: 'INTELLIGENCE', items: [{ href: '/assistant', label: 'Study assistant', Icon: Sparkles }, { href: '/insights', label: 'Insights', Icon: ChartNoAxesCombined }] },
  { section: 'PERSONAL', items: [{ href: '/schedule', label: 'My schedule', Icon: Clock3 }, { href: '/settings', label: 'Settings', Icon: Settings }] },
];
const titles: Record<string, string> = { '/': 'Dashboard', '/courses': 'My courses', '/assignments': 'Assignments & exams', '/calendar': 'Calendar', '/planner': 'Study planner', '/focus': 'Focus sessions', '/assistant': 'Study assistant', '/insights': 'Insights', '/schedule': 'My schedule', '/settings': 'Settings' };
const fmtDate = (value: string, options: Intl.DateTimeFormatOptions = { month: 'short', day: 'numeric' }) => new Intl.DateTimeFormat('en-US', options).format(new Date(`${value.slice(0,10)}T12:00:00`));
const timeText = (value: string) => new Date(value).toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' });
const id = () => Math.random().toString(36).slice(2, 9);
const courseOf = (courses: Course[], courseId?: string) => courses.find(course => course.id === courseId);
const statusTone = (status: string) => status === 'completed' || status === 'approved' ? 'green' : status === 'in progress' ? 'purple' : status === 'proposed' ? 'orange' : 'rose';

function loadState(): TimoraState {
  try { const stored = localStorage.getItem('timora-demo-v2'); if (stored) return JSON.parse(stored) as TimoraState; } catch { /* use the local demo seed */ }
  return seedState;
}

function AppShell() {
  const [path, navigate] = useLocation();
  const [data, setData] = useState<TimoraState>(loadState);
  const [modal, setModal] = useState<'task' | 'course' | 'event' | 'plan' | 'detail' | ''>('');
  const [selectedItem, setSelectedItem] = useState<AcademicItem | null>(null);
  const [query, setQuery] = useState('');
  const [toast, setToast] = useState('');
  const [taskForm, setTaskForm] = useState({ title: '', courseId: 'math', type: 'Assignment', dueDate: '2026-11-23', priority: 'medium', estimatedMinutes: '60', description: '' });
  const [courseForm, setCourseForm] = useState({ name: '', code: '', instructor: '', color: '#7664E8' });
  const [eventForm, setEventForm] = useState({ title: '', type: 'Study', date: '2026-11-16', start: '14:00', end: '15:00', courseId: '' });
  const [planForm, setPlanForm] = useState({ targetId: 'a5', availableMinutes: '180', completionDate: '2026-12-02' });
  useEffect(() => { localStorage.setItem('timora-demo-v2', JSON.stringify(data)); }, [data]);
  useEffect(() => { document.documentElement.classList.toggle('dark', Boolean(data.settings.darkMode)); document.body.classList.toggle('dark-body', Boolean(data.settings.darkMode)); }, [data.settings.darkMode]);
  useEffect(() => {
    if (!toast) return undefined;
    const timer = window.setTimeout(() => setToast(''), 2800);
    return () => window.clearTimeout(timer);
  }, [toast]);
  const update = (fn: (current: TimoraState) => TimoraState) => setData(current => fn(current));
  const pageTitle = titles[path] ?? 'Dashboard';
  const filteredItems = useMemo(() => data.items.filter(item => `${item.title} ${courseOf(data.courses, item.courseId)?.name ?? ''}`.toLowerCase().includes(query.toLowerCase())), [data.items, data.courses, query]);
  const addTask = (event: FormEvent) => {
    event.preventDefault();
    if (!taskForm.title.trim()) return;
    const item: AcademicItem = { ...taskForm, id: id(), description: taskForm.description || 'Added to your academic workload.', estimatedMinutes: Number(taskForm.estimatedMinutes), dueDate: taskForm.dueDate, priority: taskForm.priority as AcademicItem['priority'], status: 'not started', progress: 0, subtasks: [] };
    update(s => ({ ...s, items: [item, ...s.items] })); setModal(''); setTaskForm({ ...taskForm, title: '', description: '' }); setToast('Added to your workload');
  };
  const addCourse = (event: FormEvent) => {
    event.preventDefault(); if (!courseForm.name.trim() || !courseForm.code.trim()) return;
    const course: Course = { ...courseForm, id: id(), semester: 'Fall 2026', progress: 0 };
    update(s => ({ ...s, courses: [...s.courses, course] })); setModal(''); setCourseForm({ name: '', code: '', instructor: '', color: '#7664E8' }); setToast('Course added to Fall 2026');
  };
  const addEvent = (event: FormEvent) => {
    event.preventDefault(); if (!eventForm.title.trim()) return;
    const entry: ScheduleEvent = { id: id(), title: eventForm.title, type: eventForm.type, start: `${eventForm.date}T${eventForm.start}`, end: `${eventForm.date}T${eventForm.end}`, courseId: eventForm.courseId || undefined };
    if (eventForm.end <= eventForm.start) { setToast('Choose an end time after the start time'); return; }
    const overlap = data.events.find(existing => existing.start.slice(0,10) === entry.start.slice(0,10) && entry.start < existing.end && entry.end > existing.start);
    update(s => ({ ...s, events: [...s.events, entry] })); setModal(''); setToast(overlap ? `Saved with a schedule overlap: ${overlap.title}` : 'Event added to your calendar');
  };
  const createPlan = (event: FormEvent) => {
    event.preventDefault();
    const target = data.items.find(item => item.id === planForm.targetId);
    if (!target) return;
    const count = Math.max(1, Math.ceil(target.estimatedMinutes / 60));
    const sessions = Array.from({ length: count }, (_, i) => { const date = new Date('2026-11-17T12:00:00'); date.setDate(date.getDate() + i * 2); return { date: date.toISOString().slice(0,10), start: '18:00', minutes: Math.min(60, target.estimatedMinutes - i * 60), topic: i === count - 1 ? 'Review and wrap up' : `Focused work block ${i + 1}`, done: false }; });
    update(s => ({ ...s, plans: [{ id: id(), title: `${target.title} — study plan`, targetId: target.id, availableMinutes: Number(planForm.availableMinutes), completionDate: planForm.completionDate, sessions, status: target.estimatedMinutes > Number(planForm.availableMinutes) ? 'needs adjustment' : 'proposed' }, ...s.plans] }));
    setModal(''); navigate('/planner'); setToast(target.estimatedMinutes > Number(planForm.availableMinutes) ? 'Plan created — it needs more available time' : 'Draft plan is ready to review');
  };
  const toggleTask = (task: AcademicItem) => update(s => ({ ...s, items: s.items.map(item => item.id === task.id ? { ...item, status: item.status === 'completed' ? 'not started' : 'completed', progress: item.status === 'completed' ? 0 : 100 } : item) }));
  const toggleSubtask = (itemId: string, index: number) => update(s => ({ ...s, items: s.items.map(item => item.id === itemId ? (() => { const subtasks = item.subtasks.map((sub, i) => i === index ? { ...sub, done: !sub.done } : sub); const progress = subtasks.length ? Math.round(subtasks.filter(sub => sub.done).length / subtasks.length * 100) : item.progress; return { ...item, subtasks, progress, status: progress === 100 ? 'completed' as const : progress ? 'in progress' as const : 'not started' as const }; })() : item) }));
  const taskDetail = (item: AcademicItem) => { setSelectedItem(item); setModal('detail'); };

  return <div className="app-shell">
    <aside className="sidebar">
      <Link href="/" className="brand" data-testid="link-brand"><span className="brand-mark">t</span><span>timora</span></Link>
      <nav aria-label="Main navigation">{links.map(group => <div key={group.section}><div className="nav-label">{group.section}</div>{group.items.map(({ href, label, Icon }) => <Link key={href} href={href} className={`nav-link ${path === href ? 'active' : ''}`} data-testid={`link-nav-${href.slice(1) || 'dashboard'}`}><Icon /><span>{label}</span></Link>)}</div>)}</nav>
      <div className="side-bottom"><div className="profile"><div className="avatar">AM</div><div><div className="profile-name">{String(data.settings.name)}</div><div className="profile-meta">Fall 2026 · Student</div></div><MoreHorizontal size={16} color="#9995a5" /></div></div>
    </aside>
    <main className="main-area">
      <header className="topbar"><div className="crumb"><b>{pageTitle}</b><span> &nbsp;·&nbsp; Fall 2026</span></div><div className="top-actions"><label className="search-box"><Search size={15} /><input aria-label="Search your work" placeholder="Search your work" value={query} onChange={e => setQuery(e.target.value)} onKeyDown={e=>{if(e.key==='Enter')navigate('/assignments')}} data-testid="input-global-search" /></label><button className="icon-btn" aria-label="Notifications" onClick={() => setToast('You’re all caught up for now')} data-testid="button-notifications"><AlarmClock size={16} /></button><button className="icon-btn" aria-label="Quick add task" onClick={() => setModal('task')} data-testid="button-quick-add"><Plus size={17} /></button><div className="avatar">AM</div></div></header>
      <div className="content fade-in">
        {path === '/' && <Dashboard data={data} openTask={taskDetail} go={navigate} onCreate={() => setModal('task')} />}
        {path === '/courses' && <CoursesPage data={data} openTask={taskDetail} onCreate={() => setModal('course')} />}
        {path === '/assignments' && <AssignmentsPage data={data} items={filteredItems} toggleTask={toggleTask} openTask={taskDetail} onCreate={() => setModal('task')} />}
        {path === '/calendar' && <CalendarPage data={data} onCreate={() => setModal('event')} />}
        {path === '/planner' && <PlannerPage data={data} onCreate={() => setModal('plan')} update={update} go={navigate} />}
        {path === '/focus' && <FocusPage data={data} update={update} />}
        {path === '/assistant' && <AssistantPage data={data} update={update} onCreatePlan={() => setModal('plan')} />}
        {path === '/insights' && <InsightsPage data={data} />}
        {path === '/schedule' && <SchedulePage data={data} onCreate={() => setModal('event')} update={update} />}
        {path === '/settings' && <SettingsPage data={data} update={update} />}
        {!titles[path] && <NotFound go={navigate} />}
      </div>
    </main>
    <nav className="mobile-nav" aria-label="Mobile navigation">{links.flatMap(group => group.items).map(({ href, label, Icon }) => <Link href={href} key={href} className={path === href ? 'active' : ''} data-testid={`mobile-nav-${href.slice(1) || 'dashboard'}`}><Icon /><span>{label === 'Assignments & exams' ? 'Tasks' : label.split(' ')[0]}</span></Link>)}</nav>
    {modal && <Modal type={modal} close={() => setModal('')} taskForm={taskForm} setTaskForm={setTaskForm} courseForm={courseForm} setCourseForm={setCourseForm} eventForm={eventForm} setEventForm={setEventForm} planForm={planForm} setPlanForm={setPlanForm} data={data} onTask={addTask} onCourse={addCourse} onEvent={addEvent} onPlan={createPlan} item={selectedItem ? data.items.find(i => i.id === selectedItem.id) ?? selectedItem : null} toggleSubtask={toggleSubtask} toggleTask={toggleTask} />}
    {toast && <div role="status" className="toast-pop" data-testid="status-toast"><CheckCircle2 size={17} />{toast}</div>}
  </div>;
}

function Heading({ eyebrow, title, subtitle, action }: { eyebrow: string; title: string; subtitle?: string; action?: ReactNode }) {
  return <div className="page-heading"><div><div className="eyebrow">{eyebrow}</div><h1 className="page-title">{title}</h1>{subtitle && <p className="page-subtitle">{subtitle}</p>}</div>{action}</div>;
}
function Button({ children, onClick, kind = 'primary', testId, small = false }: { children: ReactNode; onClick?: () => void; kind?: 'primary' | 'soft' | 'plain'; testId?: string; small?: boolean }) {
  return <button type="button" className={`btn btn-${kind} ${small ? 'btn-sm' : ''}`} onClick={onClick} data-testid={testId}>{children}</button>;
}
function TimoMark() {
  return <svg viewBox="0 0 48 48" width="24" height="24" role="img" aria-label="Timo, Timora’s study companion">
    <path d="M13 16.5c1.3-5.2 5.2-8 11-8s9.7 2.8 11 8l2.6 14.1a5.8 5.8 0 0 1-5.7 6.9H16.1a5.8 5.8 0 0 1-5.7-6.9L13 16.5Z" fill="#8E7BE8"/>
    <path d="M14.2 13.1 11 7.8a1 1 0 0 1 1.3-1.4l6 3.2M33.8 13.1 37 7.8a1 1 0 0 0-1.3-1.4l-6 3.2" fill="#A995F2"/>
    <ellipse cx="19" cy="22" rx="1.55" ry="2" fill="#29243E"/><ellipse cx="29" cy="22" rx="1.55" ry="2" fill="#29243E"/>
    <path d="M20.4 28.4c1.9 1.7 5.3 1.7 7.2 0" fill="none" stroke="#4F438F" strokeWidth="1.6" strokeLinecap="round"/>
    <path d="m38 12 1.2 2.4 2.6.4-1.9 1.9.4 2.6-2.3-1.2-2.3 1.2.4-2.6-1.9-1.9 2.6-.4L38 12Z" fill="#D49ABF"/>
  </svg>;
}
function TaskLine({ item, data, onClick }: { item: AcademicItem; data: TimoraState; onClick: () => void }) {
  const course = courseOf(data.courses, item.courseId);
  return <button className="list-row task-line" onClick={onClick} data-testid={`row-task-${item.id}`}><span className="course-dot" style={{ background: course?.color }} /><span className="row-main"><span className="row-title">{item.title}</span><span className="row-meta">{course?.code} · {item.type}</span></span><span className={`pill ${item.priority === 'high' ? 'rose' : item.priority === 'medium' ? 'orange' : ''}`}>{item.priority}</span><span className="task-due">{fmtDate(item.dueDate)}</span><ArrowUpRight size={14} color="#aaa6b3" /></button>;
}
function Dashboard({ data, openTask, go, onCreate }: { data: TimoraState; openTask: (item: AcademicItem) => void; go: (path: string) => void; onCreate: () => void }) {
  const dueSoon = data.items.filter(item => item.status !== 'completed').sort((a,b) => a.dueDate.localeCompare(b.dueDate)).slice(0, 4);
  const todayEvents = data.events.filter(event => event.start.startsWith(today)).sort((a,b) => a.start.localeCompare(b.start));
  const weeklyGoal = Number(data.settings.dailyGoal) * 5;
  return <>
    <div className="hero-welcome"><div className="eyebrow">MONDAY, NOVEMBER 16</div><h1>Good morning, Alex.</h1><p>A full week, but a manageable one. Start with the next small thing.</p><Button onClick={() => go('/focus')} testId="button-start-focus"><Play size={14} fill="currentColor" /> Start a focus session</Button></div>
    <div className="grid grid-4">{[
      { label:'Active courses', value:data.courses.length, note:'Your Fall 2026 semester', Icon:BookOpen },
      { label:'Open assignments', value:data.items.filter(x=>x.status!=='completed'&&x.type!=='Exam').length, note:'Across all four courses', Icon:SquareCheckBig },
      { label:'Next deadline', value:'3 days', note:'Problem Set 6 · Nov 19', Icon:Clock3 },
      { label:'Study time · 7 days', value:'6.5 hrs', note:`of your ${weeklyGoal} hour weekly goal`, Icon:Target },
    ].map(stat=><div className="surface stat" key={stat.label} data-testid={`stat-${stat.label.toLowerCase().replaceAll(' ','-')}`}><div className="stat-top"><span>{stat.label}</span><stat.Icon size={15} color="#8b7be4" /></div><div className="stat-value">{stat.value}</div><div className="stat-foot">{stat.note}</div></div>)}</div>
    <div className="cols-main">
      <section className="surface"><div className="section-head"><div><h2 className="surface-title">Coming up</h2><p className="surface-note">A clear view of what needs your attention.</p></div><button className="text-action" onClick={()=>go('/assignments')} data-testid="button-view-all-tasks">View all <ArrowRight size={13}/></button></div>
        {dueSoon.map(item=><TaskLine key={item.id} item={item} data={data} onClick={()=>openTask(item)} />)}
      </section>
      <section className="surface"><div className="section-head"><div><h2 className="surface-title">Today, in rhythm</h2><p className="surface-note">{fmtDate(today,{weekday:'long',month:'long',day:'numeric'})}</p></div><button className="text-action" onClick={()=>go('/calendar')} data-testid="button-open-calendar">Calendar <ArrowRight size={13}/></button></div>
        {todayEvents.length ? todayEvents.map(event=><div key={event.id} className="timeline-row" data-testid={`event-today-${event.id}`}><span className={`timeline-dot ${event.type.toLowerCase()}`} /><span className="timeline-time">{timeText(event.start)}</span><span className="row-main"><span className="row-title">{event.title}</span><span className="row-meta">{event.type}{event.courseId ? ` · ${courseOf(data.courses,event.courseId)?.code}` : ''}</span></span></div>) : <Empty title="Space to focus" text="Nothing scheduled today. Add a study block when you’re ready." />}
      </section>
    </div>
    <div className="grid grid-2" style={{ marginTop:16 }}>
      <section className="surface"><div className="section-head"><div><h2 className="surface-title">Your study rhythm</h2><p className="surface-note">Focused time across the last 7 days</p></div><span className="pill purple">6.5 / {weeklyGoal} hrs</span></div><StudyBars sessions={data.sessions} dailyGoal={Number(data.settings.dailyGoal)*60} /></section>
      <section className="surface suggestion"><div className="suggestion-top"><div className="timo-mark"><TimoMark/></div><span className="pill purple">A gentle nudge</span></div><h3>Give the midterm a first look?</h3><p>Mathematics Midterm is about two and a half weeks away. One short review block this weekend can make the week before it feel lighter.</p><Button kind="soft" small onClick={()=>go('/planner')} testId="button-plan-midterm">Explore a study plan <ArrowRight size={13}/></Button><span className="mock-note">A contextual demo suggestion based on your saved deadlines.</span></section>
    </div>
    <section className="course-progress surface" style={{ marginTop:16 }}><div className="section-head"><div><h2 className="surface-title">Course progress</h2><p className="surface-note">A quick pulse on the semester so far.</p></div><button className="text-action" onClick={()=>go('/courses')} data-testid="button-all-courses">All courses <ArrowRight size={13}/></button></div><div className="progress-grid">{data.courses.map(c=><div className="progress-course" key={c.id} data-testid={`progress-course-${c.id}`}><div className="course-head"><span className="course-dot" style={{background:c.color}}/><span className="row-title">{c.name}</span><span className="course-percent">{c.progress}%</span></div><div className="progress"><span style={{width:`${c.progress}%`,background:c.color}}/></div></div>)}</div></section>
    <div className="quick-add-row"><span>Have something else to keep track of?</span><Button kind="plain" small onClick={onCreate} testId="button-dashboard-add-task"><Plus size={14}/> Add an assignment</Button></div>
  </>;
}
function StudyBars({sessions,dailyGoal=120}:{sessions:{date?:string;duration:number;status:string}[];dailyGoal?:number}) {
  const days=Array.from({length:7},(_,i)=>{const date=new Date(`${today}T12:00:00`);date.setDate(date.getDate()-(6-i));const key=date.toISOString().slice(0,10);const minutes=sessions.filter(session=>session.date===key&&session.status==='completed').reduce((sum,session)=>sum+session.duration,0);return{key,minutes,label:date.toLocaleDateString('en-US',{weekday:'narrow'})}});
  return <div className="chart-bars">{days.map(({key,minutes,label})=><div className="bar-group" key={key}><div className="bar-stack"><span className="bar done" style={{height:`${Math.min(100,minutes/dailyGoal*100)}%`}}/><span className="bar" style={{height:'100%'}}/></div><span className="bar-label">{label}</span></div>)}</div>;
}
function CoursesPage({ data, openTask, onCreate }: { data: TimoraState; openTask: (item: AcademicItem) => void; onCreate:()=>void }) {
  const [active, setActive] = useState(data.courses[0].id);
  const course = courseOf(data.courses, active)!;
  const courseItems = data.items.filter(item=>item.courseId===course.id);
  return <><Heading eyebrow="YOUR SEMESTER · FALL 2026" title="My courses" subtitle="Your classes, coursework and progress in one place." action={<Button onClick={onCreate} testId="button-add-course"><Plus size={15}/> Add course</Button>} />
    <div className="course-page-grid"><aside className="course-index">{data.courses.map(c=><button key={c.id} onClick={()=>setActive(c.id)} className={`course-select ${active===c.id?'chosen':''}`} data-testid={`select-course-${c.id}`}><span className="course-dot" style={{background:c.color}}/><span className="row-main"><span className="row-title">{c.name}</span><span className="row-meta">{c.code}</span></span><ChevronRight size={14}/></button>)}</aside>
    <div className="course-detail"><section className="course-banner" style={{'--course-color':course.color} as CSSProperties}><div className="eyebrow">{course.code} · {course.semester}</div><h2>{course.name}</h2><div className="course-instructor">Instructor · {course.instructor}</div><div className="course-banner-progress"><span>Semester progress</span><b>{course.progress}%</b></div><div className="progress"><span style={{width:`${course.progress}%`,background:course.color}}/></div></section>
      <div className="grid grid-2" style={{marginTop:14}}><div className="surface stat"><div className="stat-top">Upcoming work <SquareCheckBig size={15}/></div><div className="stat-value">{courseItems.filter(x=>x.status!=='completed').length}</div><div className="stat-foot">Items still in progress</div></div><div className="surface stat"><div className="stat-top">Completed <CircleCheck size={15}/></div><div className="stat-value">{courseItems.filter(x=>x.status==='completed').length}</div><div className="stat-foot">Across this course</div></div></div>
      <section className="surface" style={{marginTop:14}}><div className="section-head"><div><h2 className="surface-title">Coursework</h2><p className="surface-note">Assignments, exams and projects for {course.code}.</p></div></div>{courseItems.map(item=><TaskLine key={item.id} item={item} data={data} onClick={()=>openTask(item)}/>)}</section>
      <section className="surface resource-section" style={{marginTop:14}}><div className="section-head"><div><h2 className="surface-title">Study materials</h2><p className="surface-note">Keep your course references close by.</p></div></div><div className="material-line"><BookOpen size={16} color={course.color}/><span><b>{course.name} lecture notes</b><small>Course materials · Updated Nov 13</small></span><span className="pill">Notes</span></div></section>
    </div></div></>;
}
function AssignmentsPage({ data, items, toggleTask, openTask, onCreate }: { data: TimoraState; items: AcademicItem[]; toggleTask: (item: AcademicItem)=>void; openTask:(item:AcademicItem)=>void; onCreate:()=>void }) {
  const [courseFilter,setCourseFilter]=useState('all'),[statusFilter,setStatusFilter]=useState('all'),[priorityFilter,setPriorityFilter]=useState('all'),[view,setView]=useState<'list'|'board'>('list');
  const visible=items.filter(x=>(courseFilter==='all'||x.courseId===courseFilter)&&(statusFilter==='all'||x.status===statusFilter)&&(priorityFilter==='all'||x.priority===priorityFilter)).sort((a,b)=>a.dueDate.localeCompare(b.dueDate));
  return <><Heading eyebrow="ACADEMIC WORKLOAD" title="Assignments & exams" subtitle="Everything due, with enough room to think about what comes next." action={<Button onClick={onCreate} testId="button-create-task"><Plus size={15}/> Add coursework</Button>}/>
    <div className="workload-summary"><div><div className="eyebrow">NEXT UP</div><b>Problem Set 6: Integrals</b><span>Mathematics II · due Thursday, Nov 19</span></div><div className="summary-side"><span className="summary-count">{data.items.filter(x=>x.status!=='completed').length}</span><small>open items</small></div></div>
    <div className="toolbar"><label className="filter-select"><Filter size={14}/><select className="select" aria-label="Filter by course" value={courseFilter} onChange={e=>setCourseFilter(e.target.value)} data-testid="filter-course"><option value="all">All courses</option>{data.courses.map(c=><option value={c.id} key={c.id}>{c.code}</option>)}</select></label><select className="select" aria-label="Filter by status" value={statusFilter} onChange={e=>setStatusFilter(e.target.value)} data-testid="filter-status"><option value="all">Any status</option><option>not started</option><option>in progress</option><option>completed</option></select><select className="select" aria-label="Filter by priority" value={priorityFilter} onChange={e=>setPriorityFilter(e.target.value)} data-testid="filter-priority"><option value="all">Any priority</option><option value="high">High priority</option><option value="medium">Medium priority</option><option value="low">Low priority</option></select><div className="view-switch"><button onClick={()=>setView('list')} className={view==='list'?'selected':''} aria-label="List view" data-testid="button-list-view"><List size={15}/></button><button onClick={()=>setView('board')} className={view==='board'?'selected':''} aria-label="Board view" data-testid="button-board-view"><Columns3 size={15}/></button></div></div>
    {!visible.length?<Empty title="Nothing matches those filters" text="Try widening your search or add a new piece of coursework." action={<Button onClick={onCreate}><Plus size={14}/> Add coursework</Button>}/>:view==='list'?<section className="surface table-wrap"><table className="table"><thead><tr><th>Coursework</th><th>Course</th><th>Due date</th><th>Priority</th><th>Workload</th><th>Status</th><th></th></tr></thead><tbody>{visible.map(item=><tr key={item.id} data-testid={`table-row-${item.id}`}><td><button className="table-link" onClick={()=>openTask(item)}>{item.title}<small>{item.type}</small></button></td><td>{courseOf(data.courses,item.courseId)?.code}</td><td>{fmtDate(item.dueDate,{month:'short',day:'numeric',year:'numeric'})}</td><td><span className={`pill ${item.priority==='high'?'rose':item.priority==='medium'?'orange':''}`}>{item.priority}</span></td><td>{item.estimatedMinutes<60?`${item.estimatedMinutes} min`:`${(item.estimatedMinutes/60).toFixed(item.estimatedMinutes%60?1:0)} hrs`}</td><td><span className={`pill ${statusTone(item.status)}`}>{item.status}</span></td><td><button className="icon-btn table-check" onClick={()=>toggleTask(item)} aria-label={`${item.status==='completed'?'Reopen':'Complete'} ${item.title}`} data-testid={`button-toggle-${item.id}`}>{item.status==='completed'?<Check size={14}/>:<Circle size={14}/>}</button></td></tr>)}</tbody></table></section>:<div className="board-grid">{['not started','in progress','completed'].map(status=><section className="board-column" key={status}><div className="board-title">{status}<span>{visible.filter(x=>x.status===status).length}</span></div>{visible.filter(x=>x.status===status).map(item=><button className="task-card board-task" key={item.id} onClick={()=>openTask(item)} data-testid={`board-task-${item.id}`}><span className="pill">{item.type}</span><b>{item.title}</b><small>{courseOf(data.courses,item.courseId)?.code} · {fmtDate(item.dueDate)}</small><span className={`pill ${item.priority==='high'?'rose':item.priority==='medium'?'orange':''}`}>{item.priority} priority</span></button>)}</section>)}</div>}
    </>;
}

function CalendarPage({ data, onCreate }: { data: TimoraState; onCreate:()=>void }) {
  const [month,setMonth]=useState(new Date(2026,10,1)),[view,setView]=useState<'month'|'week'|'day'>('month'),[day,setDay]=useState(today),[filters,setFilters]=useState(['Class','Study','Personal']);
  const [selected,setSelected]=useState<ScheduleEvent|null>(null);
  const year=month.getFullYear(),monthNum=month.getMonth(),first=new Date(year,monthNum,1),startOffset=(first.getDay()+6)%7,days=new Date(year,monthNum+1,0).getDate();
  const pad=(num:number)=>String(num).padStart(2,'0');
  const dateFor=(n:number)=>`${year}-${pad(monthNum+1)}-${pad(n)}`;
  const monthEvents=data.events.filter(e=>filters.includes(e.type));
  const eventFor=(date:string)=>monthEvents.filter(e=>e.start.startsWith(date));
  const weekStart=new Date(`${day}T12:00:00`);
  weekStart.setDate(weekStart.getDate()-((weekStart.getDay()+6)%7));
  const shownDays=view==='day'?[day]:view==='week'?Array.from({length:7},(_,i)=>{const d=new Date(weekStart);d.setDate(d.getDate()+i);return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`}):[];
  const changeMonth=(delta:number)=>setMonth(new Date(year,monthNum+delta,1));
  const movePeriod=(delta:number)=>{if(view==='month'){changeMonth(delta);return;}const d=new Date(`${day}T12:00:00`);d.setDate(d.getDate()+delta*(view==='week'?7:1));setDay(d.toISOString().slice(0,10));setMonth(new Date(d.getFullYear(),d.getMonth(),1));};
  const cycleView=(next:'month'|'week'|'day')=>setView(next);
  const eventColor=(type:string)=>type==='Class'?'#f1edff':type==='Study'?'#e9f6ef':'#fff3e4';
  return <><Heading eyebrow="A WEEK THAT HAS ROOM TO BREATHE" title="Calendar" subtitle="Your classes, study time and everything that makes the week yours." action={<Button onClick={onCreate} testId="button-create-event"><CalendarPlus size={15}/> Add event</Button>}/>
    <section className="surface calendar-surface"><div className="calendar-bar"><div className="calendar-toolbar"><button className="icon-btn" onClick={()=>movePeriod(-1)} aria-label={`Previous ${view}`} data-testid="button-calendar-prev"><ChevronLeft size={16}/></button><button className="icon-btn" onClick={()=>movePeriod(1)} aria-label={`Next ${view}`} data-testid="button-calendar-next"><ChevronRight size={16}/></button><b className="calendar-month">{view==='day'?fmtDate(day,{weekday:'long',month:'long',day:'numeric',year:'numeric'}):month.toLocaleDateString('en-US',{month:'long',year:'numeric'})}</b><button className="btn btn-plain btn-sm" onClick={()=>{setMonth(new Date(2026,10,1));setDay(today)}} data-testid="button-calendar-today">Today</button></div><div className="view-switch" aria-label="Calendar view">{(['month','week','day'] as const).map(v=><button key={v} className={view===v?'selected':''} onClick={()=>cycleView(v)} data-testid={`button-calendar-${v}`}>{v}</button>)}</div></div>
      <div className="calendar-filters">{['Class','Study','Personal'].map(kind=><label key={kind}><input type="checkbox" checked={filters.includes(kind)} onChange={()=>setFilters(old=>old.includes(kind)?old.filter(x=>x!==kind):[...old,kind])} data-testid={`filter-calendar-${kind.toLowerCase()}`}/><span className={`calendar-key ${kind.toLowerCase()}`}/>{kind}</label>)}</div>
      {view==='month'&&<div className="calendar-grid" data-testid="calendar-month-grid">{['MON','TUE','WED','THU','FRI','SAT','SUN'].map(d=><div className="calendar-weekday" key={d}>{d}</div>)}{Array.from({length:startOffset},(_,i)=><div className="calendar-cell outside" key={`blank-${i}`}/>)}{Array.from({length:days},(_,i)=>{const n=i+1,date=dateFor(n),events=eventFor(date);return <button className={`calendar-cell ${date===today?'is-today':''}`} key={date} onClick={()=>{setDay(date);setView('day')}} data-testid={`calendar-date-${date}`}><span className="calendar-day">{n}</span>{events.slice(0,3).map(e=><span className="calendar-event" key={e.id} style={{background:eventColor(e.type)}} title={e.title}>{e.title}</span>)}</button>})}</div>}
      {view==='week'&&<WeekGrid days={shownDays} events={monthEvents} eventColor={eventColor} onEvent={setSelected}/>}
      {view==='day'&&<div className="day-agenda"><div className="day-head"><button className="text-action" onClick={()=>{const d=new Date(`${day}T12:00:00`);d.setDate(d.getDate()-1);setDay(d.toISOString().slice(0,10))}} data-testid="button-day-prev"><ChevronLeft size={14}/></button><b>{fmtDate(day,{weekday:'long',month:'long',day:'numeric'})}</b><button className="text-action" onClick={()=>{const d=new Date(`${day}T12:00:00`);d.setDate(d.getDate()+1);setDay(d.toISOString().slice(0,10))}} data-testid="button-day-next"><ChevronRight size={14}/></button></div>{eventFor(day).sort((a,b)=>a.start.localeCompare(b.start)).map(e=>{const overlap=data.events.some(other=>other.id!==e.id&&other.start.slice(0,10)===e.start.slice(0,10)&&e.start<other.end&&e.end>other.start);return <button className="agenda-event" key={e.id} onClick={()=>setSelected(e)} data-testid={`agenda-event-${e.id}`}><span className={`event-type-dot ${e.type.toLowerCase()}`}/><span className="agenda-time">{timeText(e.start)}<small>{timeText(e.end)}</small></span><span className="row-main"><b>{e.title}</b><small>{e.type}{e.courseId?` · ${courseOf(data.courses,e.courseId)?.code}`:''}</small></span>{overlap&&<span className="pill orange">Overlap</span>}<ArrowUpRight size={15}/></button>})}{!eventFor(day).length&&<Empty title="An open day" text="Use this space for rest, catch-up or a study block." action={<Button kind="soft" onClick={onCreate}><Plus size={14}/> Add to the day</Button>}/>}</div>}
    </section>
    {selected&&<section className="surface event-peek"><div><div className="eyebrow">EVENT DETAILS · {selected.type}</div><b>{selected.title}</b><p>{fmtDate(selected.start,{weekday:'long',month:'long',day:'numeric'})} · {timeText(selected.start)}–{timeText(selected.end)}{selected.courseId?` · ${courseOf(data.courses,selected.courseId)?.name}`:''}</p></div><button className="icon-btn" onClick={()=>setSelected(null)} aria-label="Close event details" data-testid="button-close-event"><X size={15}/></button></section>}
    </>;
}
function WeekGrid({days,events,eventColor,onEvent}:{days:string[];events:ScheduleEvent[];eventColor:(type:string)=>string;onEvent:(event:ScheduleEvent)=>void}) {
  const hours=Array.from({length:13},(_,i)=>i+8);
  return <div className="week-grid" data-testid="calendar-week-grid"><div className="week-head"/> {days.map(d=><div className="week-head" key={d}>{fmtDate(d,{weekday:'short',day:'numeric'})}</div>)}{hours.map(hour=><Fragment key={hour}><div className="time-cell">{hour>12?hour-12:hour}:00 {hour>=12?'PM':'AM'}</div>{days.map(day=>{const matches=events.filter(e=>e.start.startsWith(day)&&new Date(e.start).getHours()===hour);return <div className="week-slot" key={`${day}-${hour}`}>{matches.map(e=><button className="week-event" key={e.id} style={{background:eventColor(e.type)}} onClick={()=>onEvent(e)} data-testid={`week-event-${e.id}`}>{timeText(e.start)} {e.title}</button>)}</div>})}</Fragment>)}</div>;
}

function PlannerPage({data,onCreate,update,go}:{data:TimoraState;onCreate:()=>void;update:(fn:(s:TimoraState)=>TimoraState)=>void;go:(path:string)=>void}) {
  const [editingPlan,setEditingPlan]=useState<string|null>(null);
  const setStatus=(plan:StudyPlan,status:string)=>update(s=>({ ...s, plans:s.plans.map(p=>p.id===plan.id?{...p,status}:p), events:status==='approved'?[...s.events,...plan.sessions.map(session=>({id:id(),title:`Study · ${session.topic}`,type:'Study',start:`${session.date}T${session.start}`,end:`${session.date}T${String(Number(session.start.slice(0,2))+Math.ceil(session.minutes/60)).padStart(2,'0')}:00`,courseId:s.items.find(i=>i.id===plan.targetId)?.courseId}))]:s.events }));
  const amend=(plan:StudyPlan)=>update(s=>({...s,plans:s.plans.map(p=>p.id===plan.id?{...p,availableMinutes:p.availableMinutes+60,status:(p.availableMinutes+60)>=(s.items.find(item=>item.id===p.targetId)?.estimatedMinutes??0)?'proposed':'needs adjustment'}:p)}));
  const markSession=(plan:StudyPlan,index:number)=>update(s=>({...s,plans:s.plans.map(p=>p.id===plan.id?{...p,sessions:p.sessions.map((x,i)=>i===index?{...x,done:!x.done}:x),status:p.sessions.every((x,i)=>i===index?!x.done:x.done)?'completed':'in progress'}:p)}));
  const editSession=(plan:StudyPlan,index:number,key:'date'|'start',value:string)=>update(s=>({...s,plans:s.plans.map(p=>p.id===plan.id?{...p,sessions:p.sessions.map((session,i)=>i===index?{...session,[key]:value}:session)}:p)}));
  return <><Heading eyebrow="MAKE A PLAN THAT FITS REAL LIFE" title="Study planner" subtitle="Review a draft, make it yours, then add the sessions when you’re ready." action={<Button onClick={onCreate} testId="button-create-plan"><Plus size={15}/> Build a plan</Button>}/>
    <div className="planner-intro"><div className="planner-icon"><WandSparkles size={19}/></div><div><b>Plans are drafts until you approve them.</b><p>Suggested sessions are shaped from your deadlines and available-time estimate. Check the workload before adding them to your calendar.</p></div></div>
    {!data.plans.length?<Empty title="A blank page, in a good way" text="Choose an assignment or exam to draft your first study plan." action={<Button onClick={onCreate}><Plus size={14}/> Build a plan</Button>}/>:<div className="plan-list">{data.plans.map(plan=>{const target=data.items.find(i=>i.id===plan.targetId),course=courseOf(data.courses,target?.courseId),needed=target?.estimatedMinutes??0,timeFits=plan.availableMinutes>=needed,dateFits=plan.sessions.every(session=>session.date<=plan.completionDate),conflict=plan.sessions.some(session=>{const start=Number(session.start.slice(0,2))*60+Number(session.start.slice(3,5)),end=start+session.minutes;return data.events.some(event=>{if(event.start.slice(0,10)!==session.date)return false;const sameTargetStudy=event.type==='Study'&&event.courseId===target?.courseId&&event.title.toLowerCase().includes((target?.title.split(':')[0]??'').toLowerCase());if(sameTargetStudy)return false;const eventStart=Number(event.start.slice(11,13))*60+Number(event.start.slice(14,16)),eventEnd=Number(event.end.slice(11,13))*60+Number(event.end.slice(14,16));return start<eventEnd&&end>eventStart})}),feasible=timeFits&&dateFits&&!conflict;return <section className="surface plan-card" key={plan.id} data-testid={`plan-card-${plan.id}`}><div className="plan-top"><div><div className="eyebrow">{course?.code??'STUDY PLAN'} · FINISH BY {fmtDate(plan.completionDate)}</div><h2>{plan.title}</h2><p>{target?.title} · {Math.round(needed/60*10)/10} hrs estimated work</p></div><span className={`pill ${statusTone(plan.status)}`}>{plan.status}</span></div>
      <div className="plan-metrics"><div><span>Available time</span><b>{Math.floor(plan.availableMinutes/60)} hrs {plan.availableMinutes%60?`${plan.availableMinutes%60} min`:''}</b></div><div><span>Proposed blocks</span><b>{plan.sessions.length} sessions</b></div><div><span>Feasibility</span><b className={feasible?'feasible':'not-feasible'}>{feasible?'Fits your estimate':conflict?'Time conflict':!dateFits?'After finish date':'Needs more time'}</b></div></div>
      {!feasible&&<div className="adjust-note"><Lightbulb size={15}/>{conflict?'One or more proposed blocks overlap an event. Edit the session date or time before approval.':!dateFits?'One or more sessions fall after your finish date. Edit them to fit the deadline.':`${plan.availableMinutes} minutes available vs. ${needed} estimated. Add a study block or reduce the scope before approving.`}</div>}
      <div className="plan-sessions">{plan.sessions.map((session,i)=><div className="plan-session" key={`${plan.id}-${i}`}><button onClick={()=>markSession(plan,i)} className={`session-check ${session.done?'checked':''}`} aria-label={session.done?'Mark session open':'Mark session complete'} data-testid={`button-session-${plan.id}-${i}`}>{session.done&&<Check size={12}/>}</button><span className="row-main"><b>{session.topic}</b>{editingPlan===plan.id?<span className="session-edit-fields"><input type="date" className="field" value={session.date} onChange={e=>editSession(plan,i,'date',e.target.value)} aria-label={`Date for ${session.topic}`} data-testid={`input-plan-date-${plan.id}-${i}`}/><input type="time" className="field" value={session.start} onChange={e=>editSession(plan,i,'start',e.target.value)} aria-label={`Start time for ${session.topic}`} data-testid={`input-plan-time-${plan.id}-${i}`}/><small>{session.minutes} min</small></span>:<small>{fmtDate(session.date,{weekday:'short',month:'short',day:'numeric'})} · {session.start} · {session.minutes} min</small>}</span>{session.done&&<span className="pill green">Done</span>}</div>)}</div>
      <div className="plan-actions">{plan.status==='proposed'||plan.status==='needs adjustment'?<><Button kind="plain" small onClick={()=>setEditingPlan(editingPlan===plan.id?null:plan.id)} testId={`button-edit-plan-${plan.id}`}><SlidersHorizontal size={13}/>{editingPlan===plan.id?'Done editing':'Edit sessions'}</Button><Button kind="plain" small onClick={()=>amend(plan)} testId={`button-adjust-plan-${plan.id}`}><Plus size={13}/> Add 1 hour</Button><button className="btn btn-primary btn-sm" disabled={!feasible} onClick={()=>setStatus(plan,'approved')} data-testid={`button-approve-plan-${plan.id}`}><Check size={14}/>{feasible?'Approve plan':conflict?'Resolve conflict':'Add time to approve'}</button></>:plan.status==='approved'?<Button kind="soft" small onClick={()=>go('/calendar')} testId={`button-view-plan-calendar-${plan.id}`}>View on calendar <ArrowRight size={13}/></Button>:plan.status==='in progress'?<><Button kind="plain" small onClick={()=>setEditingPlan(editingPlan===plan.id?null:plan.id)} testId={`button-edit-plan-${plan.id}`}><SlidersHorizontal size={13}/>{editingPlan===plan.id?'Done editing':'Edit sessions'}</Button><Button kind="soft" small onClick={()=>go('/focus')} testId={`button-continue-plan-${plan.id}`}><Play size={13}/> Continue with focus</Button></>:<span className="pill green"><Check size={12}/> Plan complete</span>}</div>
    </section>})}</div>}
    <div className="planner-foot"><span>Not sure where to start?</span><button className="text-action" onClick={()=>go('/assistant')} data-testid="link-planner-assistant">Talk it through with the study assistant <ArrowRight size={13}/></button></div>
  </>;
}

function FocusPage({data,update}:{data:TimoraState;update:(fn:(s:TimoraState)=>TimoraState)=>void}) {
  const defaultLength=Number(data.settings.focusLength)||45;
  const [taskId,setTaskId]=useState('a1'),[duration,setDuration]=useState(defaultLength),[remaining,setRemaining]=useState(defaultLength*60),[running,setRunning]=useState(false),[summary,setSummary]=useState<{status:string;seconds:number}|null>(null),[reflection,setReflection]=useState('');
  const task=data.items.find(i=>i.id===taskId),course=courseOf(data.courses,task?.courseId);
  useEffect(()=>{if(!running)return;const timer=window.setInterval(()=>setRemaining(value=>{if(value<=1){window.clearInterval(timer);setRunning(false);setSummary({status:'completed',seconds:duration*60});update(s=>({...s,sessions:[{id:id(),taskId,courseId:task?.courseId??'math',duration,status:'completed',reflection:'',date:today},...s.sessions]}));return 0}return value-1}),1000);return()=>window.clearInterval(timer)},[running,duration,taskId]);
  const start=()=>{if(remaining===0)setRemaining(duration*60);setSummary(null);setRunning(true)};
  const finish=(status:'completed'|'interrupted')=>{if(status==='interrupted'&&!window.confirm('End this focus block early? You can save what you got done.'))return;setRunning(false);const elapsed=duration*60-remaining;setSummary({status,seconds:elapsed});update(s=>({...s,sessions:[{id:id(),taskId,courseId:task?.courseId??'math',duration:Math.max(1,Math.round(elapsed/60)),status,reflection:'',date:today},...s.sessions]}));};
  const saveReflection=()=>{if(!reflection.trim())return;update(s=>({...s,sessions:s.sessions.map((x,i)=>i===0?{...x,reflection}:x)}));setReflection('');setSummary(null)};
  return <><Heading eyebrow="A LITTLE SPACE TO FOCUS" title="Focus sessions" subtitle="One thing at a time. Your other tabs can wait."/>
    <div className="focus-layout"><section className="surface focus-main"><div className="focus-context"><div className="focus-kicker"><span className="course-dot" style={{background:course?.color}}/>{course?.name??'Choose a course'}</div><select className="select focus-task-select" value={taskId} onChange={e=>{setTaskId(e.target.value);setSummary(null)}} disabled={running} data-testid="select-focus-task">{data.items.filter(i=>i.status!=='completed').map(i=><option key={i.id} value={i.id}>{i.title}</option>)}</select></div>
      <div className="timer-wrap"><div className="timer-ring"><div><div className="timer-time" data-testid="text-focus-timer">{`${String(Math.floor(remaining/60)).padStart(2,'0')}:${String(remaining%60).padStart(2,'0')}`}</div><div className="timer-caption">{running?'You’re in a focus block':summary?'Block finished':'Ready when you are'}</div></div></div>
      <div className="duration-picker">{[25,45,60].map(n=><button key={n} className={duration===n?'picked':''} disabled={running} onClick={()=>{setDuration(n);setRemaining(n*60)}} data-testid={`button-duration-${n}`}>{n} min</button>)}</div>
      <div className="timer-controls">{!running?<Button onClick={start} testId="button-focus-start"><Play size={15} fill="currentColor"/> {summary?'Start another block':'Start focusing'}</Button>:<><Button kind="soft" onClick={()=>setRunning(false)} testId="button-focus-pause"><Pause size={15}/> Pause</Button><Button kind="plain" onClick={()=>finish('interrupted')} testId="button-focus-end"><X size={15}/> End early</Button></>}</div>
      {summary&&<div className="focus-summary" data-testid="focus-summary"><div className="summary-check"><Check size={17}/></div><div><b>{summary.status==='completed'?'A solid block of work.':'Your session was interrupted.'}</b><p>{Math.floor(summary.seconds/60)} minutes on {task?.title}.{summary.status==='interrupted'?' It still counts as time you gave it.':''}</p></div></div>}
      {summary&&<div className="reflection-form"><label htmlFor="reflection">A note for next time (optional)</label><div><input id="reflection" className="field" placeholder="What did you make progress on?" value={reflection} onChange={e=>setReflection(e.target.value)} data-testid="input-focus-reflection"/><Button kind="soft" onClick={saveReflection} small testId="button-save-reflection">Save note</Button></div></div>}
      </div></section>
      <aside className="focus-aside"><section className="surface"><div className="eyebrow">A GOOD WORKING RHYTHM</div><h3>Focus, then reset.</h3><p>Try one {duration}-minute block, then step away for a {Number(data.settings.breakLength)}-minute break. Your timer keeps this local to this browser.</p><div className="break-rule"><span><Timer size={15}/> Focus</span><b>{duration} min</b></div><div className="break-rule"><span><Coffee size={15}/> Break</span><b>{Number(data.settings.breakLength)} min</b></div></section><section className="surface recent-sessions"><h3 className="surface-title">Recent sessions</h3>{data.sessions.slice(0,4).map(s=><div className="list-row" key={s.id}><span className={`session-indicator ${s.status}`}/><span className="row-main"><span className="row-title">{data.items.find(x=>x.id===s.taskId)?.title??'Study session'}</span><span className="row-meta">{s.duration} min · {s.status}</span></span></div>)}</section></aside>
    </div>
    </>;
}

function AssistantPage({data,update,onCreatePlan}:{data:TimoraState;update:(fn:(s:TimoraState)=>TimoraState)=>void;onCreatePlan:()=>void}) {
  const [text,setText]=useState(''),[pending,setPending]=useState(false);
  const send=(value=text)=>{const trimmed=value.trim();if(!trimmed)return;const user:AssistantMessage={id:id(),role:'user',text:trimmed,time:new Date().toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'})};const response:AssistantMessage={id:id(),role:'assistant',text:trimmed.toLowerCase().includes('exam')||trimmed.toLowerCase().includes('midterm')?'Your Mathematics Midterm is Dec 3, and the current coursework estimate is about five hours. A few shorter review blocks over the next two weeks could fit around your classes. I can draft a plan for you to review; nothing is added until you approve it.':'Here’s what I can see in your Fall 2026 workload: Problem Set 6 is due Nov 19, the Data Structures Quiz is Nov 20, and the Database Design Project is due Nov 24. We can break one of those into smaller steps or draft a study plan. Any changes need your approval first.',time:new Date().toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'}),preview:true};update(s=>({...s,messages:[...s.messages,user,response]}));setText('');setPending(true);window.setTimeout(()=>setPending(false),500)};
  return <><Heading eyebrow="HERE TO HELP YOU THINK IT THROUGH" title="Study assistant" subtitle="A contextual demo companion, not a live AI service."/>
    <div className="assistant-layout"><section className="surface assistant-conversation"><div className="assistant-context"><div className="timo-mark"><TimoMark/></div><div><b>Your study context</b><p>4 courses · {data.items.filter(i=>i.status!=='completed').length} open items · next deadline Nov 19</p></div><span className="demo-tag">DEMO</span></div>
      <div className="chat-box" data-testid="assistant-conversation">{data.messages.map(m=><div className={`message ${m.role}`} key={m.id} data-testid={`message-${m.id}`}><div className="msg-meta">{m.role==='assistant'?'Timora · suggestion':'You'} · {m.time}</div>{m.text}{m.preview&&<div className="action-preview"><div className="eyebrow">SUGGESTED NEXT STEP</div><b>Draft a Mathematics Midterm study plan</b><p>4 review blocks · around 4 hours · by Dec 2</p><Button kind="soft" small onClick={onCreatePlan} testId="button-assistant-review-plan">Review plan <ArrowRight size={12}/></Button></div>}</div>)}{pending&&<div className="typing-indicator">Checking your saved course and deadline context…</div>}</div>
      <form className="chat-compose" onSubmit={e=>{e.preventDefault();send()}}><input className="field" placeholder="Ask about your workload or study plan…" value={text} onChange={e=>setText(e.target.value)} aria-label="Message the study assistant" data-testid="input-assistant-message"/><button className="btn btn-primary" type="submit" aria-label="Send message" data-testid="button-send-message"><Send size={15}/></button></form>
      <div className="suggested-prompts"><span>Try asking</span>{['Help me get ready for the math midterm','What should I work on this week?','Break down my database project'].map((prompt,i)=><button key={prompt} onClick={()=>send(prompt)} data-testid={`button-prompt-${i}`}>{prompt}<ArrowUpRight size={12}/></button>)}</div>
    </section><aside className="assistant-side"><div className="surface"><div className="eyebrow">YOUR CURRENT LOAD</div><h3>Manageable, with a little planning.</h3><div className="assistant-load">{data.items.filter(i=>i.status!=='completed').length}<span> open coursework items</span></div>{data.items.filter(i=>i.status!=='completed').sort((a,b)=>a.dueDate.localeCompare(b.dueDate)).slice(0,3).map(item=><div className="list-row" key={item.id}><span className="course-dot" style={{background:courseOf(data.courses,item.courseId)?.color}}/><span className="row-main"><b className="row-title">{item.title}</b><small className="row-meta">Due {fmtDate(item.dueDate)}</small></span></div>)}</div><div className="assistant-disclaimer"><Lightbulb size={15}/><span>Suggestions use your local demo data. They are not generated by an AI model and are never applied without your approval.</span></div></aside></div>
  </>;
}

function InsightsPage({data}:{data:TimoraState}) {
  const done=data.items.filter(i=>i.status==='completed').length,total=data.items.length,completion=Math.round(done/total*100);
  const sessions=data.sessions.filter(s=>s.status==='completed'),totalMins=sessions.reduce((sum,s)=>sum+s.duration,0);
  const workloadMinutes=data.items.filter(item=>item.status!=='completed').reduce((sum,item)=>sum+item.estimatedMinutes,0);
  const plannedSessions=data.plans.reduce((sum,plan)=>sum+plan.sessions.length,0);
  const perCourse=data.courses.map(c=>({...c,minutes:data.sessions.filter(s=>s.courseId===c.id).reduce((sum,s)=>sum+s.duration,0)}));
  return <><Heading eyebrow="A KINDER WAY TO SEE YOUR PROGRESS" title="Insights" subtitle="Patterns to learn from, not scores to chase." action={<span className="pill purple">Last 7 days</span>}/>
    <div className="grid grid-4">{[{label:'Focused time',value:`${Math.floor(totalMins/60)}h ${totalMins%60}m`,note:'Across completed focus sessions',Icon:Timer},{label:'Coursework complete',value:`${done} of ${total}`,note:`${completion}% of tracked items`,Icon:CircleCheck},{label:'Focus blocks',value:sessions.length,note:'Completed sessions logged',Icon:Target},{label:'Upcoming workload',value:`${(workloadMinutes/60).toFixed(1)} hrs`,note:'Estimated across open tasks',Icon:TrendingUp}].map(x=><div className="surface stat" key={x.label} data-testid={`insight-${x.label.toLowerCase().replaceAll(' ','-')}`}><div className="stat-top">{x.label}<x.Icon size={15} color="#8374db"/></div><div className="stat-value">{x.value}</div><div className="stat-foot">{x.note}</div></div>)}</div>
    <div className="grid grid-2" style={{marginTop:16}}><section className="surface"><div className="section-head"><div><h2 className="surface-title">Study time by day</h2><p className="surface-note">Completed focus time · last 7 days</p></div><span className="pill">6.5 hrs total</span></div><StudyBars sessions={data.sessions} dailyGoal={Number(data.settings.dailyGoal)*60}/><div className="chart-legend"><span><i className="legend-dot purple-dot"/>Completed</span><span><i className="legend-dot pale-dot"/>Daily goal</span></div></section>
    <section className="surface"><div className="section-head"><div><h2 className="surface-title">Time by course</h2><p className="surface-note">Where your focus has gone lately</p></div></div>{perCourse.map(c=><div className="course-time-row" key={c.id}><span className="course-dot" style={{background:c.color}}/><span className="row-main"><span className="row-title">{c.name}</span><span className="progress"><span style={{width:`${Math.min(100,c.minutes/Math.max(totalMins,1)*100)}%`,background:c.color}}/></span></span><b>{c.minutes} min</b></div>)}</section></div>
    <div className="cols-main"><section className="surface"><h2 className="surface-title">Planned and completed</h2><p className="surface-note">A quick look at how your plan is unfolding.</p><div className="comparison"><div><span>Completed coursework</span><div className="progress"><span style={{width:`${completion}%`}}/></div><b>{done} / {total}</b></div><div><span>Logged focus sessions · {plannedSessions} planned</span><div className="progress"><span style={{width:`${Math.min(100,sessions.length/Math.max(plannedSessions,1)*100)}%`,background:'#d98cac'}}/></div><b>{sessions.length} / {plannedSessions}</b></div></div></section><section className="surface reflection-card"><div className="eyebrow">A PATTERN WORTH NOTICING</div><h3>Your work comes in focused blocks.</h3><p>You’ve logged sessions of {data.sessions.slice(0,3).map(s=>`${s.duration} min`).join(', ')}. Keeping a short reflection after each block can help you spot what rhythm feels best.</p></section></div>
  </>;
}

function SchedulePage({data,onCreate,update}:{data:TimoraState;onCreate:()=>void;update:(fn:(s:TimoraState)=>TimoraState)=>void}) {
  const days=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
  const blocks=['Morning','Midday','Afternoon','Evening'];
  const initial=['Monday-Morning','Monday-Afternoon','Tuesday-Morning','Tuesday-Afternoon','Wednesday-Morning','Wednesday-Afternoon','Thursday-Morning','Thursday-Afternoon','Friday-Morning'];
  const [availability,setAvailability]=useState<string[]>(()=>{const saved=localStorage.getItem('timora-availability');return saved?JSON.parse(saved) as string[]:initial});
  const toggle=(key:string)=>setAvailability(old=>{const next=old.includes(key)?old.filter(x=>x!==key):[...old,key];localStorage.setItem('timora-availability',JSON.stringify(next));return next});
  const typeColors=(t:string)=>t==='Work'?'orange':t==='Study'?'purple':'green';
  return <><Heading eyebrow="MAKE ROOM FOR THE REST OF LIFE" title="My schedule" subtitle="Your availability shapes study plans. Personal commitments stay yours." action={<Button onClick={onCreate} testId="button-schedule-add-event"><Plus size={15}/> Add commitment</Button>}/>
    <div className="schedule-layout"><section className="surface availability-card"><div className="section-head"><div><h2 className="surface-title">Weekly availability</h2><p className="surface-note">Tap a block to mark when study time usually works for you.</p></div><span className="pill purple">{availability.length} open blocks</span></div>
      <div className="availability-grid"><div className="availability-head"/> {blocks.map(b=><div className="availability-head" key={b}>{b}</div>)}{days.map(d=><div className="availability-row" key={d}><b>{d.slice(0,3)}</b>{blocks.map(b=>{const key=`${d}-${b}`,on=availability.includes(key);return <button className={`availability-cell ${on?'available':''}`} key={key} onClick={()=>toggle(key)} aria-pressed={on} data-testid={`availability-${key.toLowerCase()}`}><span>{on?'Open':'—'}</span></button>})}</div>)}</div>
      <p className="availability-help">Your availability is saved in this browser and used as a guide for local demo plans.</p>
    </section><aside className="surface commitments"><div className="section-head"><div><h2 className="surface-title">Coming up</h2><p className="surface-note">Events in your personal calendar</p></div></div>{data.events.filter(e=>e.type==='Personal'||e.type==='Work').length?data.events.filter(e=>e.type==='Personal'||e.type==='Work').sort((a,b)=>a.start.localeCompare(b.start)).map(e=><div className="commitment-row" key={e.id}><span className={`pill ${typeColors(e.type)}`}>{e.type}</span><span className="row-main"><b className="row-title">{e.title}</b><small className="row-meta">{fmtDate(e.start,{weekday:'short',month:'short',day:'numeric'})} · {timeText(e.start)}</small></span><button className="icon-btn" aria-label={`Remove ${e.title}`} onClick={()=>update(s=>({...s,events:s.events.filter(x=>x.id!==e.id)}))} data-testid={`button-remove-event-${e.id}`}><X size={13}/></button></div>):<Empty title="No personal commitments" text="Add work, appointments or time you want to keep free." action={<Button kind="soft" small onClick={onCreate}><Plus size={13}/> Add commitment</Button>}/>}</aside></div>
      <section className="surface preference-strip"><div><div className="eyebrow">STUDY PREFERENCES</div><b>Short breaks help keep a long study day realistic.</b><p>Current default: 45 minutes of focus, then a 10 minute reset.</p></div><Link href="/settings" className="btn btn-plain btn-sm" data-testid="button-schedule-preferences">Adjust preferences <ArrowRight size={13}/></Link></section>
    </>;
}

function SettingsPage({data,update}:{data:TimoraState;update:(fn:(s:TimoraState)=>TimoraState)=>void}) {
  const setPref=(key:string,value:string|boolean)=>update(s=>({...s,settings:{...s.settings,[key]:value}}));
  const toggle=(key:string)=>setPref(key,!data.settings[key]);
  const toggleDark=()=>{const next=!data.settings.darkMode;setPref('darkMode',next);document.documentElement.classList.toggle('dark',Boolean(next));document.body.classList.toggle('dark-body',Boolean(next))};
  const clearData=()=>{if(window.confirm('Reset this local demo to its original sample data? Your changes in this browser will be cleared.')){localStorage.removeItem('timora-demo-v1');localStorage.removeItem('timora-demo-v2');localStorage.removeItem('timora-availability');window.location.reload()}};
  return <><Heading eyebrow="MAKE TIMORA FEEL LIKE YOURS" title="Settings" subtitle="Your preferences are kept in this browser for the demo."/>
    <div className="settings-layout"><nav className="settings-nav"><a href="#profile">Profile</a><a href="#academic">Academic</a><a href="#notifications">Notifications</a><a href="#study">Study preferences</a><a href="#appearance">Appearance</a></nav><div className="settings-sections">
      <section className="surface settings-section" id="profile"><div className="settings-section-head"><div className="settings-avatar">AM</div><div><h2 className="surface-title">Profile</h2><p className="surface-note">The basics, just for this prototype.</p></div></div><div className="form-grid"><FormField label="Full name"><input className="field" value={String(data.settings.name)} onChange={e=>setPref('name',e.target.value)} data-testid="input-profile-name"/></FormField><FormField label="Email address"><input className="field" value={String(data.settings.email)} onChange={e=>setPref('email',e.target.value)} data-testid="input-profile-email"/></FormField></div></section>
      <section className="surface settings-section" id="academic"><h2 className="surface-title">Academic preferences</h2><p className="surface-note">Keep your semester context current.</p><div className="form-grid settings-fields"><FormField label="Program"><input className="field" value={String(data.settings.major)} onChange={e=>setPref('major',e.target.value)} data-testid="input-major"/></FormField><FormField label="Current semester"><select className="select" value={String(data.settings.semester)} onChange={e=>setPref('semester',e.target.value)} data-testid="select-semester"><option>Fall 2026</option><option>Spring 2027</option></select></FormField></div></section>
      <section className="surface settings-section" id="notifications"><h2 className="surface-title">Notifications</h2><p className="surface-note">A nudge when it helps, quiet when it doesn’t.</p><SettingToggle title="Deadline reminders" detail="A gentle reminder before coursework is due." checked={Boolean(data.settings.reminders)} onClick={()=>toggle('reminders')} testId="toggle-reminders"/><SettingToggle title="Study session notifications" detail="Let me know when a planned block is coming up." checked={Boolean(data.settings.notifications)} onClick={()=>toggle('notifications')} testId="toggle-notifications"/><SettingToggle title="Weekly study summary" detail="A short reflection on your week, every Sunday." checked={Boolean(data.settings.weeklySummary)} onClick={()=>toggle('weeklySummary')} testId="toggle-weekly-summary"/></section>
      <section className="surface settings-section" id="study"><h2 className="surface-title">Study preferences</h2><p className="surface-note">Defaults for a study rhythm that feels sustainable.</p><div className="form-grid settings-fields"><FormField label="Daily study goal (hours)"><select className="select" value={String(data.settings.dailyGoal)} onChange={e=>setPref('dailyGoal',e.target.value)} data-testid="select-daily-goal"><option value="1">1 hour</option><option value="2">2 hours</option><option value="3">3 hours</option><option value="4">4 hours</option></select></FormField><FormField label="Focus block (minutes)"><select className="select" value={String(data.settings.focusLength)} onChange={e=>setPref('focusLength',e.target.value)} data-testid="select-focus-length"><option value="25">25 minutes</option><option value="45">45 minutes</option><option value="60">60 minutes</option></select></FormField><FormField label="Break duration (minutes)"><select className="select" value={String(data.settings.breakLength)} onChange={e=>setPref('breakLength',e.target.value)} data-testid="select-break-length"><option value="5">5 minutes</option><option value="10">10 minutes</option><option value="15">15 minutes</option></select></FormField></div></section>
      <section className="surface settings-section" id="appearance"><h2 className="surface-title">Appearance</h2><p className="surface-note">Make the workspace comfortable to look at.</p><SettingToggle title="Dark appearance" detail="Switch the interface to a softer low-light palette." checked={Boolean(data.settings.darkMode)} onClick={toggleDark} testId="toggle-dark-mode"/><div className="setting-row"><div><b>Accent color</b><small>Timora violet</small></div><span className="accent-swatch"/></div></section>
      <section className="surface settings-section integrations"><h2 className="surface-title">Connected services</h2><p className="surface-note">External integrations are intentionally not connected in this local prototype.</p><div className="setting-row"><div><b>Calendar sync</b><small>Your Timora calendar is saved only in this browser.</small></div><span className="pill">Not connected</span></div></section>
      <section className="surface settings-section"><h2 className="surface-title">Demo data</h2><p className="surface-note">Changes are local to this browser. Reset to the original Alex Morgan sample whenever you like.</p><Button kind="plain" small onClick={clearData} testId="button-reset-demo">Reset demo data</Button></section>
    </div></div>
  </>;
}
function SettingToggle({title,detail,checked,onClick,testId}:{title:string;detail:string;checked:boolean;onClick:()=>void;testId:string}) { return <div className="setting-row"><div><b>{title}</b><small>{detail}</small></div><button role="switch" aria-checked={checked} className={`switch ${checked?'on':''}`} onClick={onClick} aria-label={title} data-testid={testId}/></div>; }
function FormField({label,children}:{label:string;children:ReactNode}) { return <label className="form-field"><span>{label}</span>{children}</label>; }
function Empty({title,text,action}:{title:string;text:string;action?:ReactNode}) { return <div className="empty"><div className="empty-mark"><TimoMark/></div><b>{title}</b><p>{text}</p>{action}</div>; }

function Modal({type,close,taskForm,setTaskForm,courseForm,setCourseForm,eventForm,setEventForm,planForm,setPlanForm,data,onTask,onCourse,onEvent,onPlan,item,toggleSubtask,toggleTask}:{type:string;close:()=>void;taskForm:{title:string;courseId:string;type:string;dueDate:string;priority:string;estimatedMinutes:string;description:string};setTaskForm:(v:{title:string;courseId:string;type:string;dueDate:string;priority:string;estimatedMinutes:string;description:string})=>void;courseForm:{name:string;code:string;instructor:string;color:string};setCourseForm:(v:{name:string;code:string;instructor:string;color:string})=>void;eventForm:{title:string;type:string;date:string;start:string;end:string;courseId:string};setEventForm:(v:{title:string;type:string;date:string;start:string;end:string;courseId:string})=>void;planForm:{targetId:string;availableMinutes:string;completionDate:string};setPlanForm:(v:{targetId:string;availableMinutes:string;completionDate:string})=>void;data:TimoraState;onTask:(e:FormEvent)=>void;onCourse:(e:FormEvent)=>void;onEvent:(e:FormEvent)=>void;onPlan:(e:FormEvent)=>void;item:AcademicItem|null;toggleSubtask:(id:string,index:number)=>void;toggleTask:(item:AcademicItem)=>void}) {
  const isTask=type==='task',isCourse=type==='course',isEvent=type==='event',isPlan=type==='plan',detail=type==='detail';
  const heading=isTask?'Add coursework':isCourse?'Add a course':isEvent?'Add calendar event':isPlan?'Build a study plan':item?.title??'Details';
  const target=data.items.find(i=>i.id===planForm.targetId);
  return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)close()}}><div className="modal" role="dialog" aria-modal="true" aria-labelledby="modal-heading" data-testid={`dialog-${type}`}><div className="modal-head"><div><div className="eyebrow">{detail?'COURSEWORK DETAILS':'TIMORA · FALL 2026'}</div><h2 id="modal-heading" className="surface-title modal-title">{heading}</h2></div><button className="icon-btn" onClick={close} aria-label="Close dialog" data-testid="button-close-dialog"><X size={15}/></button></div>
    {isTask&&<form onSubmit={onTask}><div className="form-grid"><FormField label="Title"><input className="field" required autoFocus value={taskForm.title} onChange={e=>setTaskForm({...taskForm,title:e.target.value})} placeholder="e.g. Lab report draft" data-testid="input-task-title"/></FormField><FormField label="Course"><select className="select" value={taskForm.courseId} onChange={e=>setTaskForm({...taskForm,courseId:e.target.value})} data-testid="select-task-course">{data.courses.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></FormField><FormField label="Type"><select className="select" value={taskForm.type} onChange={e=>setTaskForm({...taskForm,type:e.target.value})} data-testid="select-task-type">{['Assignment','Exam','Project','Lab','Quiz'].map(x=><option key={x}>{x}</option>)}</select></FormField><FormField label="Due date"><input className="field" type="date" value={taskForm.dueDate} onChange={e=>setTaskForm({...taskForm,dueDate:e.target.value})} data-testid="input-task-due"/></FormField><FormField label="Priority"><select className="select" value={taskForm.priority} onChange={e=>setTaskForm({...taskForm,priority:e.target.value})} data-testid="select-task-priority"><option>low</option><option>medium</option><option>high</option></select></FormField><FormField label="Estimated minutes"><input className="field" type="number" min="10" step="5" value={taskForm.estimatedMinutes} onChange={e=>setTaskForm({...taskForm,estimatedMinutes:e.target.value})} data-testid="input-task-estimate"/></FormField><FormField label="Description" ><textarea className="textarea" rows={3} value={taskForm.description} onChange={e=>setTaskForm({...taskForm,description:e.target.value})} placeholder="What does this work involve?" data-testid="input-task-description"/></FormField></div><div className="modal-actions"><Button kind="plain" onClick={close}>Cancel</Button><button className="btn btn-primary" type="submit" data-testid="button-save-task"><Plus size={14}/> Add to workload</button></div></form>}
    {isCourse&&<form onSubmit={onCourse}><div className="form-grid"><FormField label="Course name"><input className="field" required autoFocus value={courseForm.name} onChange={e=>setCourseForm({...courseForm,name:e.target.value})} placeholder="e.g. Cognitive Science" data-testid="input-course-name"/></FormField><FormField label="Course code"><input className="field" required value={courseForm.code} onChange={e=>setCourseForm({...courseForm,code:e.target.value.toUpperCase()})} placeholder="e.g. PSY 205" data-testid="input-course-code"/></FormField><FormField label="Instructor"><input className="field" value={courseForm.instructor} onChange={e=>setCourseForm({...courseForm,instructor:e.target.value})} placeholder="Instructor name" data-testid="input-course-instructor"/></FormField><FormField label="Course color"><select className="select" value={courseForm.color} onChange={e=>setCourseForm({...courseForm,color:e.target.value})} data-testid="select-course-color"><option value="#7664E8">Violet</option><option value="#E28AAF">Rose</option><option value="#53A88B">Sage</option><option value="#E3A14F">Amber</option></select></FormField></div><div className="modal-actions"><Button kind="plain" onClick={close}>Cancel</Button><button className="btn btn-primary" type="submit" data-testid="button-save-course"><Plus size={14}/> Add course</button></div></form>}
    {isEvent&&<form onSubmit={onEvent}><div className="form-grid"><FormField label="Event name"><input className="field" required autoFocus value={eventForm.title} onChange={e=>setEventForm({...eventForm,title:e.target.value})} placeholder="What’s happening?" data-testid="input-event-title"/></FormField><FormField label="Category"><select className="select" value={eventForm.type} onChange={e=>setEventForm({...eventForm,type:e.target.value})} data-testid="select-event-type">{['Study','Class','Personal','Work'].map(x=><option key={x}>{x}</option>)}</select></FormField><FormField label="Date"><input className="field" type="date" value={eventForm.date} onChange={e=>setEventForm({...eventForm,date:e.target.value})} data-testid="input-event-date"/></FormField><FormField label="Course (optional)"><select className="select" value={eventForm.courseId} onChange={e=>setEventForm({...eventForm,courseId:e.target.value})} data-testid="select-event-course"><option value="">No course</option>{data.courses.map(c=><option key={c.id} value={c.id}>{c.code}</option>)}</select></FormField><FormField label="Starts"><input className="field" type="time" value={eventForm.start} onChange={e=>setEventForm({...eventForm,start:e.target.value})} data-testid="input-event-start"/></FormField><FormField label="Ends"><input className="field" type="time" value={eventForm.end} onChange={e=>setEventForm({...eventForm,end:e.target.value})} data-testid="input-event-end"/></FormField></div><div className="modal-actions"><Button kind="plain" onClick={close}>Cancel</Button><button className="btn btn-primary" type="submit" data-testid="button-save-event"><CalendarPlus size={14}/> Save event</button></div></form>}
    {isPlan&&<form onSubmit={onPlan}><p className="modal-intro">Build a feasible draft from a deadline and a realistic time budget. Review every proposed session before it reaches your calendar.</p><div className="form-grid"><FormField label="Assignment or exam"><select className="select" value={planForm.targetId} onChange={e=>setPlanForm({...planForm,targetId:e.target.value})} data-testid="select-plan-target">{data.items.filter(i=>i.status!=='completed').map(i=><option value={i.id} key={i.id}>{i.title}</option>)}</select></FormField><FormField label="Available study time (minutes)"><input className="field" type="number" min="30" step="30" value={planForm.availableMinutes} onChange={e=>setPlanForm({...planForm,availableMinutes:e.target.value})} data-testid="input-plan-time"/></FormField><FormField label="Finish by"><input className="field" type="date" value={planForm.completionDate} onChange={e=>setPlanForm({...planForm,completionDate:e.target.value})} data-testid="input-plan-date"/></FormField></div><div className={`plan-preview ${Number(planForm.availableMinutes)>=(target?.estimatedMinutes??0)?'good':'warning'}`}><Target size={16}/><span>{target?.estimatedMinutes} minutes estimated · {planForm.availableMinutes} available. {Number(planForm.availableMinutes)>=(target?.estimatedMinutes??0)?'The draft fits your time estimate.':'This draft will be flagged for adjustment before approval.'}</span></div><div className="modal-actions"><Button kind="plain" onClick={close}>Cancel</Button><button className="btn btn-primary" type="submit" data-testid="button-save-plan"><WandSparkles size={14}/> Create draft</button></div></form>}
    {detail&&item&&<div className="detail-content"><div className="detail-course"><span className="course-dot" style={{background:courseOf(data.courses,item.courseId)?.color}}/>{courseOf(data.courses,item.courseId)?.name} · {item.type}</div><p>{item.description}</p><div className="detail-metrics"><span><small>Due</small><b>{fmtDate(item.dueDate,{weekday:'short',month:'long',day:'numeric'})}</b></span><span><small>Estimated work</small><b>{item.estimatedMinutes} min</b></span><span><small>Priority</small><b className={item.priority}>{item.priority}</b></span></div><div className="detail-progress"><div><b>Progress</b><span>{item.progress}%</span></div><div className="progress"><span style={{width:`${item.progress}%`}}/></div></div><div className="subtask-list"><b>Checklist</b>{item.subtasks.length?item.subtasks.map((sub,index)=><button className={`subtask ${sub.done?'done':''}`} key={sub.title} onClick={()=>toggleSubtask(item.id,index)} data-testid={`button-subtask-${item.id}-${index}`}><span className="subtask-check">{sub.done&&<Check size={11}/>}</span>{sub.title}</button>):<p className="muted-text">No checklist yet. You can track completion with the button below.</p>}</div><div className="modal-actions"><Button kind="plain" onClick={close}>Close</Button><Button onClick={()=>{toggleTask(item);close()}} kind={item.status==='completed'?'soft':'primary'} testId="button-detail-toggle-status">{item.status==='completed'?'Reopen task':'Mark complete'}</Button></div></div>}
  </div></div>;
}

function NotFound({go}:{go:(path:string)=>void}) { return <div className="not-found surface"><div className="empty-mark"><Search size={18}/></div><h2>That page isn’t here.</h2><p>Choose a section from your workspace to get back on track.</p><Button onClick={()=>go('/')} testId="button-back-home">Back to dashboard <ArrowRight size={14}/></Button></div>; }

function RoutedContent() {
  const [location] = useLocation();
  return <ErrorBoundary resetKey={location}><Switch><Route><AppShell/></Route></Switch></ErrorBoundary>;
}
function App() {
  return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><RoutedContent/></WouterRouter><Toaster/></TooltipProvider></QueryClientProvider>;
}
export default App;
